import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Fraction of each candidate's uncoloured neighbours that currently have exactly one legal colour."""
    k = adjacency.shape[0]
    if k == 0:
        return np.zeros(0)
    c = neighbor_colors.shape[1]
    if c == 0:
        return np.zeros(k)
    n_legal = (neighbor_colors == 0).sum(axis=1)
    near_forced = (n_legal == 1).astype(float)
    uncoloured_degree = adjacency.sum(axis=1).astype(float)
    counts = adjacency.astype(float) @ near_forced
    return counts / np.maximum(uncoloured_degree, 1.0)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Saturation (fraction of used colours present among neighbours) divided by 1 + size of the colour class the candidate would take."""
    k = neighbor_colors.shape[0]
    c = neighbor_colors.shape[1]
    if c == 0:
        return np.zeros(k)
    is_free = (neighbor_colors == 0)
    t = np.where(is_free.any(1), is_free.argmax(1), c)
    ind = (neighbor_colors > 0).astype(float)
    sat = ind.sum(1) / float(c)
    cs = np.concatenate([color_sizes.astype(float), [0.0]])
    return sat / (1.0 + cs[t])

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Fraction of a candidate's uncoloured neighbours whose uncoloured degree is strictly smaller than its own."""
    u_deg = adjacency.sum(axis=1).astype(float)
    lower = ((u_deg[None, :] < u_deg[:, None]) & adjacency).sum(axis=1).astype(float)
    return lower / np.maximum(u_deg, 1.0)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Sum over colours j of (share of candidate's coloured neighbours in colour j)^2 times (size of class j / size of largest class); 0 when c=0 or no coloured neighbours."""
    k, c = neighbor_colors.shape
    if c == 0:
        return np.zeros(k)
    m = neighbor_colors.sum(axis=1)
    p = neighbor_colors / np.maximum(m, 1)[:, None]
    w = color_sizes / max(color_sizes.max(), 1)
    return ((p * p) * w).sum(axis=1)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Size-weighted colour concentration: Herfindahl of neighbour mass per colour, mass = neighbour count * class size."""
    k = neighbor_colors.shape[0]
    c = neighbor_colors.shape[1]
    if c == 0:
        return np.zeros(k)
    mass = neighbor_colors.astype(float) * color_sizes[None, :]
    tot = mass.sum(axis=1, keepdims=True)
    safe = np.maximum(tot, 1e-12)
    p = np.where(tot > 0, mass / safe, 0.0)
    return (p ** 2).sum(axis=1)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Global contrast of uncoloured degree vs the mean, scaled by the spread of the *whole* uncoloured set's degree distribution (std), not the range."""
    k = adjacency.shape[0]
    if k < 2:
        return np.zeros(k, dtype=float)
    d = adjacency.sum(axis=1).astype(float)
    mu = d.mean()
    sd = d.std()
    if sd <= 0.0:
        return np.zeros(k, dtype=float)
    return (d - mu) / max(sd, 1.0)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Ratio of the candidate's coloured-neighbour count to its uncoloured-neighbour count, revealing how 'finished' a vertex's surroundings are."""
    k = neighbor_colors.shape[0]
    if k == 0:
        return np.zeros(0)
    colored_nbrs = neighbor_colors.sum(axis=1).astype(float)
    uncolored_nbrs = adjacency.sum(axis=1).astype(float)
    total = colored_nbrs + uncolored_nbrs
    ratio = (colored_nbrs + 0.5) / (uncolored_nbrs + 0.5)
    out = np.log1p(ratio) / np.log1p(degree.astype(float) + 2.0)
    return np.clip(np.nan_to_num(out, nan=0.0), -1.0, 1.0)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Sum of colour-class sizes over colours used by exactly one uncoloured neighbour, divided by graph size."""
    k, c = neighbor_colors.shape
    if c == 0:
        return np.zeros(k)
    used = (neighbor_colors > 0).astype(float)
    cnt = adjacency.astype(float) @ used
    sizes = color_sizes.astype(float)
    n = float(k + sizes.sum())
    if n <= 0:
        return np.zeros(k)
    return ((cnt == 1).astype(float) @ sizes) / n
